#include <stdio.h>

/* estatisticasDeNotas le notas inteiras digitadas e imprime TRES linhas:
     media <numero com casas decimais>
     maxima <inteiro>
     aprovados <inteiro>
   A lista termina sempre com -1, e o -1 nao entra em conta nenhuma.
   Sempre vem ao menos uma nota antes do -1. Aprovado e nota >= 6. */
void estatisticasDeNotas(void) {
    int nota = 0;
    int soma = 0;
    int quantas = 0;
    int maxima = 0;
    int aprovados = 0;

    /* 1) escreva aqui o while: leia com scanf enquanto a leitura der certo
          (== 1) E a nota nao for negativa (nota >= 0). No corpo, atualize
          soma, quantas, maxima (quando a nota alcancar a maxima) e aprovados
          (quando a nota for 6 ou mais). */

    /* 2) escreva aqui a linha da media: um printf com %f e o cast antes da
          barra, no formato "media <numero>". Ela vem ANTES das duas de baixo. */

    printf("maxima %d\n", maxima);
    printf("aprovados %d\n", aprovados);
}

