/* teste do desafio estatisticas-de-notas — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Cada cenario escreve num arquivo o que a pessoa "digitaria", aponta o
   stdin para esse arquivo (freopen), captura o stdout no proprio teste e le
   as tres linhas de volta. Os nomes dos arquivos temporarios sao POR
   CENARIO: um cenario nunca le a entrada nem a captura do outro. Nunca ha
   fclose de stdin/stdout — so fflush — para o proximo freopen ficar legal
   (C11 7.21.4).
   As quatro listas dao quatro trios de resposta DIFERENTES: nenhum texto
   fixo passa nos quatro. A media de 10 e 5 e 7.5, o que reprova quem
   esquecer o cast; a maxima do terceiro cenario esta no MEIO da lista, o
   que reprova quem imprimir a primeira ou a ultima nota; e aprovados
   difere de quantas em dois cenarios, o que reprova quem trocar um pelo
   outro. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void estatisticasDeNotas(void);

SM_TEST(tres_notas_media_exata) {
    /* o que a pessoa digita nesta rodada */
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "7 8 9 -1\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    /* captura: o stdout vira o arquivo sm_saida_1.tmp */
    freopen("sm_saida_1.tmp", "w", stdout);
    estatisticasDeNotas();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
