#include <stdio.h>

void estatisticasDeNotas(void) {
    int nota = 0;
    int soma = 0;
    int quantas = 0;
    int maxima = 0;
    int aprovados = 0;

    while (scanf("%d", &nota) == 1 && nota >= 0) {
        soma += nota;
        quantas++;
        if (nota >= maxima) {
            maxima = nota;
        }
        if (nota >= 6) {
            aprovados++;
        }
    }

    printf("media %f\n", (double)soma / quantas);
    printf("maxima %d\n", maxima);
    printf("aprovados %d\n", aprovados);
}
